{
    public static async Task RunAsync(string directory,Action<bool,string> check)
    {
        var original=ProceduralFixture.Create();var rig=SurfaceContactChecks.Profile(original.Scene);var targetBase=ProceduralFixture.Create(1.2f);var targetRig=SurfaceContactChecks.Profile(targetBase.Scene);
        var first=new AnimationClip(Guid.NewGuid(),"Shared name",24,new(60),false,[]);var second=first with{Id=Guid.NewGuid(),Revision=Guid.NewGuid()};var source=original with{Clips=[first,second],NativeLayers=[]};var target=targetBase with{Clips=[],Contacts=[],NativeLayers=[]};string sourceBefore=RetargetDependencies.Hash(source),rigBefore=AnimationControls.DeformChecksum(target.Scene);
        check(RetargetDependencies.SourceKey(source,first,rig,new())!=RetargetDependencies.SourceKey(source,second,rig,new())&&RetargetDependencies.ProfileKey(source.Scene,target.Scene,RootMotionPolicy.Preserve)!=RetargetDependencies.ProfileKey(target.Scene,source.Scene,RootMotionPolicy.Preserve),"Dependency hashes include stable clip identities and directional source/target geometry rather than empty anonymous records");
        var baseline=RetargetService.Bake(source,first,rig,target,targetRig,useContacts:false).Value!;var neutral=RetargetService.Bake(source,first,rig,target,targetRig,useContacts:false,fitting:new()).Value!;
        check(PoseEqual(target.Scene,baseline.Clip,neutral.Clip),"Neutral fitting controls reproduce the automatic baseline at withheld fractional samples");
        var altered=baseline.Clip with{Tracks=baseline.Clip.Tracks.Where(t=>t.Bone!=target.Scene.Bones[2].Name).Append(new BoneTrack(target.Scene.Bones[2].Name,[null,null,null,null,null,new([new(0,90)]),null,null,null])).ToArray()};
        var action=RetargetAcceptance.MeasureAction(target.Scene,altered,f=>AnimationService.Evaluate(target.Scene,baseline.Clip,f),[2]);
        check(!action.Passed&&Math.Abs(action.MaximumDegrees-90)<.001f&&action.Bone==target.Scene.Bones[2].Name,"Independent action guard measures a 90-degree torso distortion even if contact residuals happen to pass");
        var bodyAction=RetargetAcceptance.MeasureAction(target.Scene,altered,f=>AnimationService.Evaluate(target.Scene,baseline.Clip,f),[2,4,5,6],rig:targetRig,bodyFittingAt:_=>true);
        check(bodyAction.Passed&&bodyAction.MaximumBodyAdjustmentDegrees>89&&bodyAction.MaximumWorldDegrees>89&&bodyAction.MaximumDegrees<.1f,"Supported waist/chest adjustment carries the arms in the body frame and records its full world correction separately");
        var distortedArm=altered with{Tracks=altered.Tracks.Where(t=>t.Bone!=target.Scene.Bones[4].Name).Append(new BoneTrack(target.Scene.Bones[4].Name,[null,null,null,null,new([new(0,80)]),null,null,null,null])).ToArray()};
        check(!RetargetAcceptance.MeasureAction(target.Scene,distortedArm,f=>AnimationService.Evaluate(target.Scene,baseline.Clip,f),[2,4,5,6],rig:targetRig,bodyFittingAt:_=>true).Passed,"Allowed body fitting does not hide an unrelated 80-degree arm distortion");
        var bodyPhases=new[]{new SupportSurfacePhase(0,3,SupportSurfaceMode.Ground)};
        check(SurfaceContacts.BodySupportedAt(bodyPhases,false,false,3.875,24)&&!SurfaceContacts.BodySupportedAt(bodyPhases,false,false,4,24)&&!SurfaceContacts.BodySupportedAt(bodyPhases,true,false,24,24),"Body support has a precise get-up release and separately measured actual closing sample");
        var beforeRelease=new ContactFrame(Guid.NewGuid(),first.Id,0,rig.SkeletonFingerprint,[]){EndFrame=4,EndExclusive=true};var afterRelease=beforeRelease with{Frame=4,EndFrame=23,EndExclusive=false};
        check(beforeRelease.Contains(3.999)&&!beforeRelease.Contains(4)&&afterRelease.Contains(4),"Derived half-open contact phases never double-lock the exact body-support release frame");
        var contactPass=new ContactValidation(RetargetAcceptance.Version,true,true,.0001f,.0001f,0,0,0,0,0,0,1,1,1);
        check(!RetargetAcceptance.Ready(contactPass,[new("ACTION_FIDELITY_REVIEW","Measured unintended action correction",false)],[],true),"Numerically valid contacts cannot bypass action-fidelity review through Apply");
        var height=RetargetService.Bake(source,first,rig,target,targetRig,useContacts:false,fitting:new(){PelvisHeight=.05f}).Value!;var basis=AnimationService.Evaluate(target.Scene,baseline.Clip,5.375);var raised=AnimationService.Evaluate(target.Scene,height.Clip,5.375);float leg=RigCharacterization.Describe(target.Scene,targetRig).LegLength;
        check(Math.Abs(raised.World[1].Translation.Y-basis.World[1].Translation.Y-.05f*leg)<.00001f&&raised.World[0].Translation==basis.World[0].Translation,"Pelvis height changes existing target pose by the requested leg-relative amount while preserving root policy");
        var arms=RetargetService.Bake(source,first,rig,target,targetRig,useContacts:false,fitting:new(){ArmSpacingDegrees=12,FreeHandReach=.9f,BodyLeanDegrees=7}).Value!;
        check(Vector3.Distance(AnimationService.Evaluate(target.Scene,arms.Clip,4.375).World[targetRig.Chains.First(c=>c.Role=="Hand.L").Effector].Translation,basis.World[targetRig.Chains.First(c=>c.Role=="Hand.L").Effector].Translation)>.01f,"Arm spacing, free-hand reach and body lean produce real target end-effector changes");
        var sourcePose=AnimationService.Evaluate(source.Scene,first,0);var pins=rig.Chains.Where(c=>c.Role.StartsWith("Foot.")).Select(c=>ContactSolver.Capture(source.Scene,sourcePose,rig,c.Role)).ToArray();var locked=source with{Contacts=[new ContactFrame(Guid.NewGuid(),first.Id,0,rig.SkeletonFingerprint,pins){EndFrame=23}]};
        var planted=RetargetService.Bake(locked,first,rig,target,targetRig,fitting:new(){PelvisHeight=-.1f,ArmSpacingDegrees=30,StanceWidth=1.5f,FreeHandReach=.8f});
        check(planted.Value is not null&&planted.Value.Contacts.SelectMany(c=>c.Pins).All(p=>ContactGeometry.Residual(p,AnimationService.Evaluate(target.Scene,planted.Value.Clip,7.375)).Length()<.0002f),"Extreme artistic preferences preserve authored hard foot pins without changing skeleton lengths");
        var clock=new AnimationClock();clock.Speed=2;clock.Play(first);clock.Advance(.05,first);check(first.SampleCount==24&&first.DurationSeconds==.4&&!first.Loop&&RetargetDependencies.Hash(source)==sourceBefore,"Preview speed alters no source keys, duration, contacts or native loop flag");
        var moving=first with{Tracks=[new("Root",[null,null,null,null,null,null,new([new(0,0,1,1),new(24,24,1,1)]),null,null])]};var timedSource=source with{Clips=[moving]};
        var timed=RetargetService.Bake(timedSource,moving,rig,target,targetRig,useContacts:false,timing:new(){TrimStartSeconds=4d/60,TrimEndSeconds=20d/60,ExportSpeed=2}).Value!;
        var timedPose=AnimationService.Evaluate(target.Scene,timed.Clip,2.5);float ratio=RigCharacterization.Describe(target.Scene,targetRig).LegLength/RigCharacterization.Describe(source.Scene,rig).LegLength;
        check(timed.Clip.SampleCount==8&&Math.Abs(timedPose.World[0].Translation.X-9*ratio)<.00001f&&Math.Abs(timed.Clip.Retarget!.SourceSecondsAt(2.5/60)-9d/60)<1e-12,"Combined trim and export speed sample the authentic source phase and persist comparison time mapping");
        check(timed.Clip.LastKeyFrame==8&&!timed.Clip.Loop&&Math.Abs(AnimationService.Evaluate(target.Scene,timed.Clip,7.875).World[0].Translation.X-19.75f*ratio)<.00001f,"Trim/retime retains a separate non-loop boundary key and the actual last fractional source phase without adding a displayed sample");
        var finalClock=new AnimationClock();finalClock.Play(timed.Clip);finalClock.Advance(7.5/60,timed.Clip);check(finalClock.Playing&&Math.Abs(finalClock.Frame-7.5)<1e-10,"Displayed one-shot transport reaches the final fractional segment instead of stopping a full native frame early");finalClock.Advance(.5/60,timed.Clip);check(!finalClock.Playing&&finalClock.Frame<8&&finalClock.Frame>7.99,"One-shot playback stops at end-exclusive duration and keeps the next state's first sample separate");
        var retimedPins=RetargetService.Bake(locked,first,rig,target,targetRig,timing:new(){TrimStartSeconds=4d/60,TrimEndSeconds=20d/60,ExportSpeed=2}).Value!;
        check(retimedPins.Contacts.Single().Frame==0&&retimedPins.Contacts.Single().EndFrame==8&&retimedPins.Source.Contacts.Single().EndFrame==23,"Retiming moves derived contact boundaries together while authentic source intervals remain unchanged");
        check(RetargetService.Bake(timedSource,moving,rig,target,targetRig,useContacts:false,timing:new(){ExportSpeed=1.3}).Value is null,"Nonintegral native duration is an explicit timing conflict, never silently rounded");
        check(RetargetService.Bake(timedSource with{Moves=[new(Guid.NewGuid(),"Protected","test",[new(12,12,"Hit")])]},moving,rig,target,targetRig,timing:new(){ExportSpeed=2}).Value is null,"Protected gameplay intervals block unsupported retiming instead of shifting their events silently");
        var jumping=moving with{Tracks=[moving.Tracks[0] with{Channels=[null,null,null,null,null,null,new([new(0,0),new(23,2)]),new([new(0,0),new(11,1),new(23,0)]),null]}]};var jumpSource=source with{Clips=[jumping]};var jump=RetargetService.Bake(jumpSource,jumping,rig,target,targetRig,RootMotionPolicy.InPlace,useContacts:false).Value!;
        check(Math.Abs(AnimationService.Evaluate(target.Scene,jump.Clip,11).World[0].Translation.Y-ratio)<.00001f&&jump.Clip.Retarget!.ExtractedActorMotion.All(k=>k.Translation.Y==0)&&jump.Clip.Retarget.ExtractedActorMotion[^1].Translation.X>1.9f*ratio,"Explicit horizontal in-place extraction preserves vertical jumps and retains paired actor travel rather than discarding it");
        var held=first with{Tracks=[new("Arm.L",[null,null,null,null,null,new([new(0,0),new(10,20)],Interpolation.Step),null,null,null])]};check(RetargetService.Bake(source with{Clips=[held]},held,rig,target,targetRig,useContacts:false,timing:new(){ExportSpeed=1.5}).Value is null,"Retiming rejects a nonintegral held-pose boundary even when total native sample count is integral");
        var observation=RetargetDependencies.Analyze(source,first,rig,new());
        var released=ContactPolicies.Apply(source,first,rig,observation.Ground.Contacts,observation.Ground,[new("Foot.L",4d/60,8d/60,ContactTimeDomain.TargetSeconds,ContactEditAction.Release)],new(){TrimStartSeconds=2d/60,ExportSpeed=2},new(60));
        check(released.Where(c=>c.Contains(12)).SelectMany(c=>c.Pins).All(p=>p.Role!="Foot.L")&&released.Where(c=>c.Contains(8)).SelectMany(c=>c.Pins).Any(p=>p.Role=="Foot.L")&&released.Where(c=>c.Contains(20)).SelectMany(c=>c.Pins).Any(p=>p.Role=="Foot.L"),"Target-seconds contact override maps through trim and retiming and preserves surrounding source contact phases");
        var sliding=ContactPolicies.Apply(source,first,rig,observation.Ground.Contacts,observation.Ground,[new("Foot.L",0,23d/60,ContactTimeDomain.SourceSeconds,ContactEditAction.AllowSlide)],new(),new(60));
        check(sliding.SelectMany(c=>c.Pins).Any(p=>p.Role=="Foot.L"&&p.Mode==ContactMode.Slide&&p.PlaneNormal is not null&&p.SurfaceRegion.Length>0&&p.Automatic),"Explicit slide changes only the inferred surface degrees of freedom and records semantic provenance");
        bool pinBlocked=false;try{ContactPolicies.Apply(locked,first,rig,locked.Contacts,observation.Ground,[new("Foot.L",0,.1,ContactTimeDomain.SourceSeconds,ContactEditAction.Release)],new(),new(60));}catch(InvalidOperationException){pinBlocked=true;}check(pinBlocked,"Inferred-interval release cannot weaken an authored exact pin");
        bool frameBlocked=false;try{ContactPolicies.Apply(source,first,rig,observation.Ground.Contacts,observation.Ground,[new("Foot.L",4,8,ContactTimeDomain.ProtectedGameFrame,ContactEditAction.Release)],new(){ExportSpeed=2},new(60));}catch(NotSupportedException){frameBlocked=true;}check(frameBlocked,"Protected target game-frame contact edits report a precise trim/retime ownership conflict");
        var motion=new NativeResourceRef(Path.Combine(directory,"original-surface-fixture"),"root/0/0","original-surface-proof","CHR0",4){ContainerEntry="root/0"};var shape=motion with{Entry="root/0/1",Format="SHP0"};
        var morphClip=first with{Name="Original surface morph",Source=new(Guid.NewGuid(),motion,null,source.Scene.SkeletonRevision,new(60)){NativeName="Original surface morph"}};
        int footMesh=Array.FindIndex(source.Scene.Meshes,m=>m.Vertices.Any(v=>(int)v.Joints.X==12));check(footMesh>=0,"Original geometry fixture independently identifies the left shoe mesh");
        var morphLayer=new NativeAnimationLayer(Guid.NewGuid(),"Original surface morph","SHP0",24,false,new(60),shape,[],"Original authored geometry fixture"){Morphs=[new("Shoe",footMesh,MorphAttribute.Position,[new("Raised sole",new([new(0,1)]),source.Scene.Meshes[footMesh].Vertices.Select(v=>new Vector4(v.Position+((int)v.Joints.X==12?new Vector3(0,.2f,0):Vector3.Zero),0)).ToArray())])]};
        var morphSource=source with{Clips=[morphClip],NativeLayers=[morphLayer]};var baseAnalysis=SurfaceContacts.Detect(morphSource with{NativeLayers=[]},morphClip,rig,new());var shapedAnalysis=SurfaceContacts.Detect(morphSource,morphClip,rig,new());
        check(baseAnalysis.Contacts.SelectMany(c=>c.Pins).Any(p=>p.Role=="Foot.L")&&shapedAnalysis.Contacts.SelectMany(c=>c.Pins).All(p=>p.Role!="Foot.L")&&shapedAnalysis.Contacts.SelectMany(c=>c.Pins).Any(p=>p.Role=="Foot.R"),"Contact detection evaluates the actual same-name SHP0 shoe geometry with CHR0 instead of claiming a base-mesh plant");
        var doc=new EditorDocument(target);using var batch=new RetargetBatch(doc,source,rig,targetRig,[first.Id,second.Id],ground:new());batch.SaveSharedPresetOnApply=true;
        int preparations=doc.SceneFingerprintPreparations;doc.Clock.Play(first);for(int i=0;i<90;i++){doc.Tick(.01);_ =doc.CurrentContacts;_ =doc.Evaluate();}doc.Clock.Playing=false;check(doc.SceneFingerprintPreparations==preparations,"Prepared playback and contact overlays do not hash rigs, decode or run contact optimization on each tick");
        await batch.RunAsync();await File.WriteAllTextAsync(Path.Combine(directory,"batch-initial.json"),JsonSerializer.Serialize(batch.Receipt(),ProjectStore.Json));check(batch.Rows.All(r=>r.State==RetargetRowState.Validated&&r.Validation?.Passed==true),"Same-source batch analyzes and validates each independent clip using real skinned contacts");
        check(batch.Rows[0].TargetName!=batch.Rows[1].TargetName&&batch.Rows.Select(r=>r.Source.Id).Distinct().Count()==2,"Duplicate display names retain stable clip IDs and receive independent collision-free target names");
        var single=RetargetService.Bake(source,first,rig,target,targetRig,ground:new()).Value!;check(PoseEqual(target.Scene,single.Clip,batch.Rows[0].Bake!.Clip),"Single and batch paths produce the same actual baked fractional target poses");
        batch.SetOverride(second.Id,new(){ArmSpacingDegrees=10});check(batch.Rows[0].State==RetargetRowState.Validated&&batch.Rows[1].State==RetargetRowState.Stale,"One per-clip override invalidates only its row and retains the previous candidate as stale");
        batch.SetShared(new(){ArmSpacingDegrees=5});check(batch.Rows[1].Settings.ArmSpacingDegrees==10&&batch.Rows[0].Settings.ArmSpacingDegrees==5,"Shared settings preserve explicit per-clip overrides and update inherited values");
        await batch.RunAsync();batch.Apply();check(doc.Project.Clips.Length==2&&doc.Project.RetargetBatches.Single().Rows.All(r=>r.State==RetargetRowState.Applied),"Batch Apply commits keys, recipes, contacts, ancestry and receipts together");
        var committed=doc.Project;doc.Undo();check(ReferenceEquals(doc.Project,target),"One Undo restores the complete prior target after a multi-animation Apply");doc.Redo();check(ReferenceEquals(doc.Project,committed),"Redo restores the stored validated batch without rerunning analysis or solving");
        string saved=Path.Combine(directory,"retarget-batch.fighterport");await ProjectStore.SaveAsync(doc.Project,saved);var reopened=await ProjectStore.LoadAsync(saved);
        using(var storage=JsonDocument.Parse(await File.ReadAllTextAsync(saved))){check(storage.RootElement.GetProperty("LibraryContexts").EnumerateObject().Count()==1&&ReferenceEquals(reopened.LibrarySources[0].Scene,reopened.LibrarySources[1].Scene),"Batch persistence stores one authentic scene/layer/model context and restores shared immutable data instead of duplicating textured models per clip");}
        check(RetargetDependencies.Hash(doc.Project)==RetargetDependencies.Hash(reopened),"Pooled project save/reopen preserves the complete canonical content fingerprint");
        check(reopened.FittingProfiles.Single().Settings.ArmSpacingDegrees==5&&reopened.RetargetBatches.Single().Rows.Single(r=>r.SourceClip==second.Id).Overrides.ArmSpacingDegrees==10&&reopened.Clips.All(c=>c.Retarget?.AcceptanceProfile==RetargetAcceptance.Version),"Shared preset, clip overrides, effective recipes and acceptance receipts survive save/restart");
        var invalid=first with{Id=Guid.NewGuid(),Revision=Guid.NewGuid(),Name="Foreign bones",Tracks=[new("Absent",[new([new(0,1)]),null,null,null,null,null,null,null,null])]};var mixedSource=source with{Clips=[first,invalid]};var mixedDoc=new EditorDocument(target);using var mixed=new RetargetBatch(mixedDoc,mixedSource,rig,targetRig,[first.Id,invalid.Id],ground:new());await mixed.RunAsync();
        bool rejected=false;try{mixed.Apply();}catch(InvalidOperationException){rejected=true;}check(rejected&&mixed.Rows[0].State==RetargetRowState.Validated&&mixed.Rows[1].State==RetargetRowState.Unresolved&&mixedDoc.Project.Clips.Length==0,"Mixed batch failures preserve successful candidates and block default incomplete Apply");
        var vertex=source.Scene.Meshes[0].Vertices[0];var unsupportedPin=new ContactPin(Guid.NewGuid(),"Foot.L",rig.Chains.Single(c=>c.Role=="Foot.L").Effector,Vector3.Zero,Vector3.Zero,Quaternion.Identity,false,"Needs reviewed target skin correspondence"){SurfacePoints=[new(vertex.Position,vertex.Joints,vertex.Weights)]};
        var previewSource=source with{Clips=[moving],Contacts=[new ContactFrame(Guid.NewGuid(),moving.Id,0,rig.SkeletonFingerprint,[unsupportedPin]){EndFrame=23}]};var previewDoc=new EditorDocument(target);using var previewBatch=new RetargetBatch(previewDoc,previewSource,rig,targetRig,[moving.Id],ground:new());bool earlyPreview=false;
        previewBatch.Changed+=()=>{if(previewBatch.Rows[0].State==RetargetRowState.Analyzing&&previewBatch.Rows[0].UnfittedPreview is not null)earlyPreview=true;};await previewBatch.RunAsync();var previewRow=previewBatch.Rows[0];
        check(earlyPreview&&previewRow.State==RetargetRowState.Unresolved&&previewRow.Bake is null&&previewRow.UnfittedPreview?.Clip.Retarget is {IsDraft:true,Validation:null},"Unresolved contact fitting retains the selected motion as an explicitly unfitted preview published before the solver");
        var previewMotion=previewRow.UnfittedPreview!;check(Vector3.Distance(AnimationService.Evaluate(target.Scene,previewMotion.Clip,3.375).World[0].Translation,AnimationService.Evaluate(target.Scene,previewMotion.Clip,7.75).World[0].Translation)>1,"Unfitted target preview evaluates the selected source motion at actual fractional times instead of an old idle clip");
        rejected=false;try{previewBatch.Apply(true);}catch(InvalidOperationException){rejected=true;}check(rejected&&ReferenceEquals(previewDoc.Project,target)&&previewBatch.Receipt().Rows.Single().TargetClip is null,"An unfitted preview cannot become an applied result or alter the target document");
        previewBatch.SetOverride(moving.Id,new(){ArmSpacingDegrees=4});check(previewRow.State==RetargetRowState.Stale&&previewRow.UnfittedPreview is null,"Changing preview settings invalidates the uncommitted FK draft immediately");
        mixed.Apply(true);check(mixedDoc.Project.Clips.Length==1&&mixedDoc.Project.RetargetBatches.Single().Rows.Count(r=>r.State==RetargetRowState.Applied)==1,"Explicit Apply passed rows records the actual subset without claiming complete selected-set success");
        var staleDoc=new EditorDocument(target);using var stale=new RetargetBatch(staleDoc,source,rig,targetRig,[first.Id],ground:new());bool edited=false;stale.Changed+=()=>{if(!edited&&stale.Rows[0].State==RetargetRowState.Solving){edited=true;staleDoc.Transaction("Concurrent edit",p=>p with{Name="Edited during solve"});staleDoc.Undo();}};await stale.RunAsync();rejected=false;try{stale.Apply();}catch(InvalidOperationException){rejected=true;}check(edited&&rejected&&stale.Rows[0].State==RetargetRowState.Stale,"Target edit followed by Undo still rejects a late bake through the monotonic content version");
        var cancelDoc=new EditorDocument(target);using var cancelled=new RetargetBatch(cancelDoc,source,rig,targetRig,[first.Id],ground:new());cancelled.Changed+=()=>{if(cancelled.Rows[0].State==RetargetRowState.Solving)cancelled.Cancel();};try{await cancelled.RunAsync();}catch(OperationCanceledException){}check(ReferenceEquals(cancelDoc.Project,target)&&cancelled.Rows[0].State==RetargetRowState.Cancelled,"Cancellation before commit leaves the target unchanged and cannot regain Apply eligibility");
        var overrideDoc=new EditorDocument(target);using var superseded=new RetargetBatch(overrideDoc,source,rig,targetRig,[first.Id],ground:new());bool supersede=false;superseded.Changed+=()=>{if(!supersede&&superseded.Rows[0].State==RetargetRowState.Solving){supersede=true;superseded.SetOverride(first.Id,new(){ArmSpacingDegrees=8});}};await superseded.RunAsync();check(superseded.Rows[0].State==RetargetRowState.Stale&&superseded.Rows[0].Validation is null,"Settings changed during work cancel the obsolete request and never publish its result as current");
        var registrationDoc=new EditorDocument(target);bool registrationCurrent=true;using var registration=new RetargetBatch(registrationDoc,source,rig,targetRig,[first.Id],ground:new(),sourceCurrent:()=>registrationCurrent);registration.Changed+=()=>{if(registration.Rows[0].State==RetargetRowState.Solving)registrationCurrent=false;};await registration.RunAsync();rejected=false;try{registration.Apply();}catch(InvalidOperationException){rejected=true;}check(rejected&&registration.Rows[0].State==RetargetRowState.Stale&&registrationDoc.Project.Clips.Length==0,"Source re-registration during solving rejects late publication and Apply even if the loaded source object itself is unchanged");
        check(sourceBefore==RetargetDependencies.Hash(source)&&rigBefore==AnimationControls.DeformChecksum(target.Scene),"Recipe controls, retiming, batches and Undo preserve immutable sources and native deform data");
    }
    static bool PoseEqual(Scene scene,AnimationClip a,AnimationClip b)=>new[]{0d,.375,3.125,7.75,12.375,22.875}.All(f=>AnimationService.Evaluate(scene,a,f).World.Zip(AnimationService.Evaluate(scene,b,f).World).All(p=>Vector3.Distance(p.First.Translation,p.Second.Translation)<.00001f&&Math.Abs(Quaternion.Dot(PoseGeometry.Rotation(p.First),PoseGeometry.Rotation(p.Second)))>.999999f));
}
